// flm:_runtime: the prelude's helpers, imported by every API module and by
// flm:_entry. It imports nothing, so no module cycle exists.
//
// This file is hand-written, as are flm:_entry (entry.js) and the sandbox
// (sandbox.js). The API modules under js/api/ (flm:core/stage, …) and the
// module flm:_api that imports them all are generated by the test
// `tests/api_surface.rs` from the sources under `flm-ext/src/api/`; the
// fragments they copy are under js/hand/.
//
// The glue (`__flm`, installed by the binding before any module runs) answers
// every native call with an envelope, the JSON text `{"ok": value}` or
// `{"err": data, "message": text}`; `native` unwraps it and throws an
// `FlmError` for a failure.

const GLUE = globalThis.__flm;

// The handle base class: a façade class extends it and holds the token
// `{ kind, call, index }` of the object it stands for, and nothing else.
export class Handle {
  constructor(token) { this._token = token; }
  toJSON() { return { "@handle": this._token }; }
}

// The durable base class: the class of an object the adapter keeps beyond
// the call that answered it (a template language) extends it and holds the
// token `{ kind, table, index }` of the object, and nothing else. The token is
// plain data, valid on every engine instance and every thread for the life
// of the durable table of the feature that made it; under another registry
// it is stale.
export class Durable {
  constructor(token) { this._token = token; }
  toJSON() { return { "@durable": this._token }; }
}

// The error a failure of the boundary is thrown as: `kind` is the `ExtError`
// variant's name ("stale_handle", "argument", …), `data` its `data()` map,
// `message` its text.
export class FlmError extends Error {
  constructor(data, message) {
    super(message ?? data?.detail ?? data?.kind ?? "the extension interface failed");
    this.name = "FlmError";
    this.kind = data?.kind ?? "handler";
    this.data = data ?? null;
  }
}

// One native call: unwraps the envelope, throws `FlmError` for a failure.
function native(name, ...args) {
  const reply = JSON.parse(GLUE[name](...args));
  if ("err" in reply) throw new FlmError(reply.err, reply.message);
  return reply.ok;
}

// The classes of the handle kinds, filled by each API module at load.
const CLASSES = Object.create(null);

// Registers `cls` as the class of the objects of kind `kind`, per-call
// handles and durable tokens alike.
export function register_class(kind, cls) { CLASSES[kind] = cls; }

// Turns every `{"@handle": token}` and every `{"@durable": token}` inside
// `value` into an instance of the class of its kind (a `Handle` or a
// `Durable` when no module registered one). The instance is made without
// running the class's constructor, since a class whose constructor
// dispatches to Rust (`new UserDefinition(definition)`) answers such an
// instance. A kind with both forms has one class (`CompiledTemplate`: a
// variant's template is a per-call handle, a compiled template a durable
// token): an instance revived from `@durable` of a class that does not extend
// `Durable` writes `@durable` back.
export function revive(value) {
  if (Array.isArray(value)) return value.map(revive);
  if (value === null || typeof value !== "object") return value;
  const keys = Object.keys(value);
  if (keys.length === 1 && keys[0] === "@handle") {
    const token = value["@handle"];
    const cls = CLASSES[token?.kind] ?? Handle;
    const instance = Object.create(cls.prototype);
    instance._token = token;
    return instance;
  }
  if (keys.length === 1 && keys[0] === "@durable") {
    const token = value["@durable"];
    const cls = CLASSES[token?.kind] ?? Durable;
    const instance = Object.create(cls.prototype);
    instance._token = token;
    if (!(instance instanceof Durable)) {
      Object.defineProperty(instance, "toJSON", { value: Durable.prototype.toJSON });
    }
    return instance;
  }
  const out = {};
  for (const key of keys) out[key] = revive(value[key]);
  return out;
}

// One call into Rust: `target` is a handle (a façade instance or a module's
// token), `args` a list; answers the revived result.
export function call(target, method, args) {
  return revive(native("call", JSON.stringify(target), method, JSON.stringify(args)));
}

// The token of the API module `path` ("lang/text", …), on which its free
// functions and constructors are called: `call(module("lang/text"), "chars_text", [nodes])`.
export function module(path) { return native("module_handle", path); }

// What `register` declares while it runs: the extension's stem, the package
// and the feature, whether this run is a rehearsal (a builder that
// dispatches nothing), the stage, hook, rule-body, rewrite-stage, citation
// provider and template module objects recorded by name, the handler aspects
// recorded by element (`aspects`: element → { Referenceable, Sectioning }),
// and the late-initialization hooks and finalizers recorded by position
// (`late_inits`, `finalizers`: the n-th call of `b.late_init` or
// `b.finalizer` is at n). Set by flm/_entry around every `register`, and
// around every finalizer (which records into the same object).
let REGISTERING = null;

export function begin_registering(stem, pkg, feature, rehearsal) {
  REGISTERING = {
    stem, pkg, feature, rehearsal,
    stages: new Map(), hooks: new Map(), lowers: new Map(), rewrites: new Map(),
    providers: new Map(), templates: new Map(),
    aspects: new Map(), late_inits: [], finalizers: [],
  };
}

// Records into `done`, what an earlier `register` of the feature recorded
// (a finalizer declares on behalf of its feature), `rehearsal` as given.
export function continue_registering(done, rehearsal) {
  REGISTERING = done;
  REGISTERING.rehearsal = rehearsal;
}

// What the running `register` has recorded so far, or `null` when none
// runs: a template module's `describe` runs inside the `register` that
// contributes the module, before that `register` ends.
export function registering_now() { return REGISTERING; }

export function end_registering() {
  const done = REGISTERING;
  REGISTERING = null;
  return done;
}

// What `register` declares; `what` is the text of the refusal when no
// `register` runs ("the stage `x` must be declared").
function registering(what) {
  if (REGISTERING === null) {
    throw new FlmError({ kind: "handler", detail: `${what} while a feature's \`register\` runs` });
  }
  return REGISTERING;
}

// The feature whose `register` runs.
export function registering_feature() { return registering("the builder's `feature()` must be called").feature; }

// Whether the running `register` is a rehearsal.
export function rehearsing() { return REGISTERING !== null && REGISTERING.rehearsal; }

// Records the stage object `stage` under `name`.
export function record_stage(name, stage) { registering(`the stage \`${name}\` must be declared`).stages.set(name, stage); }

// Records the expansion hook `hook` of the element `element` and lends it:
// answers the handle of kind `expand` the builder's methods take.
export function lend_expand(element, hook) {
  registering(`the expansion hook of the element \`${element}\` must be attached`).hooks.set(element, hook);
  const policy = typeof hook.policy === "function" ? hook.policy() : "per-plan";
  return revive(native("lend_expand", element, policy));
}

// Records the body `body` of the lowering rule `rule`.
export function record_lower(rule, body) {
  registering(`the lowering rule \`${rule}\` must be built`).lowers.set(rule, body);
}

// Lends the body of the lowering rule `rule`, recorded by `record_lower`:
// answers the handle of kind `lower` that `LoweringRule::new` takes.
export function lend_lower(rule) { return revive(native("lend_lower", rule)); }

// Lends a stage of the script's own, its declaration and needs given.
export function lend_stage(decl, needs) {
  return revive(native("lend_stage", JSON.stringify(decl), JSON.stringify(needs)));
}

// Records the rewrite stage object `stage` under its stage name `name`.
export function record_rewrite(name, stage) {
  registering(`the rewrite stage \`${name}\` must be declared`).rewrites.set(name, stage);
}

// Lends a rewrite stage of the script's own, its declaration and needs
// given: answers the handle of kind `rewrite_stage` that
// `FeatureBuilder.rewrite_stage` takes.
export function lend_rewrite(decl, needs) {
  return revive(native("lend_rewrite", JSON.stringify(decl), JSON.stringify(needs)));
}

// Records the citation provider `provider` under its name `name`; a
// second object under one name in one `register` is refused.
export function record_provider(name, provider) {
  record_handler("providers", "the citation provider", name, provider);
}

// Records the template module `template` under its name `name`; a second
// object under one name in one `register` is refused.
export function record_template(name, template) {
  record_handler("templates", "the template module", name, template);
}

// Records the handler object `object` under `name` in the map `kind` of the
// running `register`; `what` names its kind in the refusals.
function record_handler(kind, what, name, object) {
  const running = registering(`${what} \`${name}\` must be contributed`);
  if (running[kind].has(name)) {
    throw new FlmError({
      kind: "handler",
      detail: `${what} \`${name}\` must be contributed once by \`register\` of the feature \`${running.feature}\` of the package \`${running.pkg}\` of the extension \`${running.stem}\``,
    });
  }
  running[kind].set(name, object);
}

// Lends the citation provider named `name`, recorded by `record_provider`:
// answers the handle of kind `citation_provider` the builder's
// `contribute_to` and `peer_slot` take.
export function lend_provider(name) { return revive(native("lend_provider", name)); }

// Lends the template module named `name`, recorded by `record_template`:
// answers the handle of kind `template_module`.
export function lend_template(name) { return revive(native("lend_template", name)); }

// The two service slots that take a handler object, as
// `flm:stdcore/features/citations` and `flm:stdcore/features/compose` export
// them (this module imports nothing).
const PROVIDERS_SLOT = "flm.citations.providers";
const TEMPLATES_SLOT = "flm.compose.templates";

// The methods a handler object of either slot may have.
const HANDLER_METHODS = ["answer", "answer_all", "describe", "files", "render"];

// Whether `value` is an object with methods: a function among its own
// properties or among the methods of a provider or a template module (a
// class's methods are on its prototype). Such a value is not data.
function has_methods(value) {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
  return Object.values(value).some(item => typeof item === "function")
    || HANDLER_METHODS.some(method => typeof value[method] === "function");
}

// What the builder's `contribute_to`, `contribute_first_to` and `peer_slot`
// send for `value`. The slot's name decides: in the two handler slots, any
// object (a function too) is a handler object, recorded by its `name` (a
// template module in the templates' slot, a citation provider in the
// providers' slot) and, unless `rehearsal`, lent: its handle (`null` in a
// rehearsal, which dispatches nothing); an object without a name or
// without the methods its kind needs is lent under the empty name, which
// the adapter refuses with the text saying what the object must have. In
// every other slot, and for a value that is not an object, the value is
// data, sent as it is; an object with methods given to such a slot is not
// data and is lent under the empty name, for the adapter's refusal saying
// which slots take an object.
export function contributed(slot, value, rehearsal) {
  const template = slot === TEMPLATES_SLOT;
  if (!template && slot !== PROVIDERS_SLOT) {
    if (!has_methods(value)) return value;
    return rehearsal ? null : lend_provider("");
  }
  const object = typeof value === "function" || (value !== null && typeof value === "object" && !Array.isArray(value));
  if (!object) return value;
  const has = method => typeof value[method] === "function";
  const name = typeof value.name === "string" ? value.name : "";
  const complete = name !== "" && (template ? has("describe") && has("render") : has("answer") || has("answer_all"));
  if (complete && template) record_template(name, value);
  if (complete && !template) record_provider(name, value);
  if (rehearsal) return null;
  const lent = complete ? name : "";
  return template ? lend_template(lent) : lend_provider(lent);
}

// The methods a handler aspect's object may have, by the aspect's kind.
const ASPECT_METHODS = Object.freeze({
  Referenceable: Object.freeze(["points"]),
  Sectioning: Object.freeze(["level", "in_toc", "toc_title"]),
});

// Records the handler object `object` of the aspect of kind `kind`
// ("Expand", "Referenceable" or "Sectioning") of the element `element`.
export function record_aspect(kind, element, object) {
  const done = registering(`the aspect \`${kind}\` of the element \`${element}\` must be attached`);
  if (kind === "Expand") {
    done.hooks.set(element, object);
    return;
  }
  const recorded = done.aspects.get(element) ?? {};
  recorded[kind] = object;
  done.aspects.set(element, recorded);
}

// Records the handler object `object` of the aspect of kind `kind` of the
// element `element` and lends it: answers the handle of kind `expand`,
// `referenceable` or `sectioning` that an aspect holds. The names of the
// object's methods go with the lent object, so that a `Sectioning` without
// `in_toc` or `toc_title` answers the defaults without a call.
export function lend_aspect(kind, element, object) {
  if (kind === "Expand") return lend_expand(element, object);
  record_aspect(kind, element, object);
  const methods = (ASPECT_METHODS[kind] ?? []).filter(name => typeof object?.[name] === "function");
  return revive(native("lend_aspect", kind, element, JSON.stringify(methods)));
}

// The aspect `aspect` (`{ Expand: object }`, `{ Referenceable: object }`,
// `{ Sectioning: object }`, or a data aspect) for the element `element`: a
// handler object not yet lent is recorded under the element and, when
// `lend`, lent, the aspect then holding its handle; anything else is
// answered as it is.
export function aspect_for(element, aspect, lend) {
  for (const kind of ["Expand", "Referenceable", "Sectioning"]) {
    const object = aspect?.[kind];
    if (object === undefined || object instanceof Handle) continue;
    if (!lend) {
      record_aspect(kind, element, object);
      return aspect;
    }
    return { [kind]: lend_aspect(kind, element, object) };
  }
  return aspect;
}

// Records the late-initialization hook `hook`: answers its position.
export function record_late_init(hook) {
  const done = registering("a late-initialization hook must be registered");
  done.late_inits.push(hook);
  return done.late_inits.length - 1;
}

// Records the finalizer `hook`: answers its position.
export function record_finalizer(hook) {
  const done = registering("a finalizer must be registered");
  done.finalizers.push(hook);
  return done.finalizers.length - 1;
}

// Lends the late-initialization hook at the position `index`: answers the
// handle of kind `late_init` that `FeatureBuilder::late_init` takes.
export function lend_late_init(index) { return revive(native("lend_late_init", index)); }

// Lends the finalizer at the position `index`: answers the handle of kind
// `finalizer` that `FeatureBuilder::finalizer` takes.
export function lend_finalizer(index) { return revive(native("lend_finalizer", index)); }
